3	use ecow::{EcoVec, eco_format, eco_vec};
4	use typst_library::diag::{At, SourceDiagnostic, SourceResult, bail, error, warning};
5	use typst_library::engine::Engine;
6	use typst_library::foundations::{
7	    Array, Capturer, Closure, ClosureNode, Content, ContextElem, Dict, Func,
8	    NativeElement, Selector, Str, Value, ops,
9	};
10	use typst_library::introspection::{Counter, State};
11	use typst_syntax::ast::{self, AstNode};
12	use typst_syntax::{DiagSpan, Span, SubRange};
13	use typst_utils::singleton;
14	
15	use crate::{CapturesVisitor, Eval, FlowEvent, Vm};
16	
17	impl Eval for ast::Code<'_> {
18	    type Output = Value;
19	
20	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
21	        eval_code(vm, &mut self.exprs())
22	    }
23	}
24	
25	/// Evaluate a stream of expressions.
26	fn eval_code<'a>(
27	    vm: &mut Vm,
28	    exprs: &mut impl Iterator<Item = ast::Expr<'a>>,
29	) -> SourceResult<Value> {
30	    let flow = vm.flow.take();
31	    let mut output = Value::None;
32	
33	    while let Some(expr) = exprs.next() {
34	        let span = expr.span();
35	        let value = match expr {
36	            ast::Expr::SetRule(set) => {
37	                let styles = set.eval(vm)?;
38	                if vm.flow.is_some() {
39	                    break;
40	                }
41	
42	                let tail = eval_code(vm, exprs)?.display();
43	                Value::Content(tail.styled_with_map(styles))
44	            }
45	            ast::Expr::ShowRule(show) => {
46	                let recipe = show.eval(vm)?;
47	                if vm.flow.is_some() {
48	                    break;
49	                }
50	
51	                let tail = eval_code(vm, exprs)?.display();
52	                Value::Content(tail.styled_with_recipe(
53	                    &mut vm.engine,
54	                    vm.context,
55	                    recipe,
56	                )?)
57	            }
58	            _ => expr.eval(vm)?,
59	        };
60	
61	        output = ops::join(output, value).at(span)?;
62	
63	        if let Some(event) = &vm.flow {
64	            warn_for_discarded_content(&mut vm.engine, event, &output);
65	            break;
66	        }
67	    }
68	
69	    if flow.is_some() {
70	        vm.flow = flow;
71	    }
72	
73	    Ok(output)
74	}
75	
76	impl Eval for ast::Expr<'_> {
77	    type Output = Value;
78	
79	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
80	        let span = self.span();
81	        let forbidden = |name| {
82	            error!(span, "{name} is only allowed directly in code and content blocks")
83	        };
84	
85	        let value = match self {
86	            Self::Text(v) => v.eval(vm).map(Value::Content),
87	            Self::Space(v) => v.eval(vm).map(Value::Content),
88	            Self::Linebreak(v) => v.eval(vm).map(Value::Content),
89	            Self::Parbreak(v) => v.eval(vm).map(Value::Content),
90	            Self::Escape(v) => v.eval(vm),
91	            Self::Shorthand(v) => v.eval(vm),
92	            Self::SmartQuote(v) => v.eval(vm).map(Value::Content),
93	            Self::Strong(v) => v.eval(vm).map(Value::Content),
94	            Self::Emph(v) => v.eval(vm).map(Value::Content),
95	            Self::Raw(v) => v.eval(vm).map(Value::Content),
96	            Self::Link(v) => v.eval(vm).map(Value::Content),
97	            Self::Label(v) => v.eval(vm),
98	            Self::Ref(v) => v.eval(vm).map(Value::Content),
