413	/// Emits a warning when we discard content while returning unconditionally.
414	fn warn_for_discarded_content(engine: &mut Engine, event: &FlowEvent, joined: &Value) {
415	    let FlowEvent::Return(span, Some(_), false) = event else { return };
416	    let Value::Content(tree) = &joined else { return };
417	
418	    let selector = singleton!(
419	        Selector,
420	        Selector::Or(eco_vec![State::select_any(), Counter::select_any()])
421	    );
422	
423	    let mut warning = warning!(
424	        *span,
425	        "this return unconditionally discards the content before it";
426	        hint: "try omitting the `return` to automatically join all values";
427	    );
428	
429	    if tree.query_first_naive(selector).is_some() {
430	        warning.hint("state/counter updates are content that must end up in the document to have an effect");
431	    }
432	
433	    engine.sink.warn(warning);
434	}
